static inline int parameter_is_effect(unsigned id) { return (id>=PARAM_CHORUS_RATE && id<=PARAM_EFFECT_MIX) || (id>=PARAM_EQ_FIRST && id<=PARAM_EQ_LAST) || (id>=PARAM_DELAY_FIRST && id<=PARAM_DELAY_LAST) || (id>=PARAM_TUBE_FIRST && id<=PARAM_TUBE_LAST) || (id>=PARAM_REVERB_FIRST && id<=PARAM_REVERB_LAST) || (id>=PARAM_DYNAMICS_FIRST && id<=PARAM_DYNAMICS_LAST) || (id>=PARAM_PHASER_FIRST && id<=PARAM_PHASER_LAST) || (id>=PARAM_FLANGER_FIRST && id<=PARAM_FLANGER_LAST); }
typedef struct { unsigned parameter,owner,slot; } ParameterTarget;
/* Common control metadata; independent of project layout and UI addresses. */
enum { PARAMETER_CONTINUOUS, PARAMETER_INTEGER, PARAMETER_TOGGLE, PARAMETER_LOGARITHMIC };
typedef struct {
    unsigned id;
    const char *name;
    float low,high,initial;
    int kind;
} ParameterDescriptor;
const ParameterDescriptor *parameter_descriptor(unsigned id);
